/**
 * Domain-level service for Contact records.
 *
 * Runs with the sharing rules of the current user and enforces
 * object/field-level security on the underlying query.
 */
public with sharing class ContactDomainService {

    /**
     * Returns the contacts belonging to the given accounts, grouped by the
     * lower-cased domain part of their email address.
     *
     * - Contacts without an email are ignored.
     * - A null or empty set of account ids yields an empty map.
     * - Every returned Contact has Id, Email and AccountId populated.
     *
     * @param accountIds the ids of the accounts whose contacts are grouped
     * @return map of lower-cased email domain -> contacts with that domain
     */
    public static Map<String, List<Contact>> groupByEmailDomain(Set<Id> accountIds) {
        Map<String, List<Contact>> contactsByDomain = new Map<String, List<Contact>>();

        if (accountIds == null || accountIds.isEmpty()) {
            return contactsByDomain;
        }

        // Defensive copy without nulls so the bind variable is clean.
        Set<Id> cleanAccountIds = new Set<Id>();
        for (Id accountId : accountIds) {
            if (accountId != null) {
                cleanAccountIds.add(accountId);
            }
        }
        if (cleanAccountIds.isEmpty()) {
            return contactsByDomain;
        }

        List<Contact> contacts = [
            SELECT Id, Email, AccountId
            FROM Contact
            WHERE AccountId IN :cleanAccountIds
              AND Email != null
            WITH USER_MODE
        ];

        for (Contact con : contacts) {
            String domain = extractDomain(con.Email);
            if (domain == null) {
                continue;
            }

            List<Contact> domainContacts = contactsByDomain.get(domain);
            if (domainContacts == null) {
                domainContacts = new List<Contact>();
                contactsByDomain.put(domain, domainContacts);
            }
            domainContacts.add(con);
        }

        return contactsByDomain;
    }

    /**
     * Extracts the lower-cased domain part of an email address.
     *
     * @param email the email address
     * @return the lower-cased domain, or null if it cannot be determined
     */
    private static String extractDomain(String email) {
        if (String.isBlank(email)) {
            return null;
        }
        Integer atIndex = email.lastIndexOf('@');
        if (atIndex < 0 || atIndex == email.length() - 1) {
            return null;
        }
        String domain = email.substring(atIndex + 1).trim().toLowerCase();
        return String.isBlank(domain) ? null : domain;
    }
}
