/**
 * Pure unit tests for InvoicingService.invoiceWonOpportunities.
 *
 * No DML, no SOQL and no callouts: the billing gateway, the selector and the
 * unit of work are ApexMocks stubs injected through the Application factories,
 * and all record ids come from fflib_IDGenerator.
 */
@IsTest(IsParallel=true)
private class InvoicingServiceTest {

    private static final String CLOSED_WON = 'Closed Won';

    // ---------------------------------------------------------------------
    // Guard clauses
    // ---------------------------------------------------------------------

    @IsTest
    static void returnsZeroAndDoesNothingWhenIdsAreNull() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
        IBillingGateway gateway = (IBillingGateway) mocks.mock(IBillingGateway.class);
        IOpportunitiesSelector selector = (IOpportunitiesSelector) mocks.mock(OpportunitiesSelector.class);
        fflib_ISObjectUnitOfWork uow = (fflib_ISObjectUnitOfWork) mocks.mock(fflib_ISObjectUnitOfWork.class);

        mocks.startStubbing();
        mocks.when(selector.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.stopStubbing();

        Application.Service.setMock(IBillingGateway.class, gateway);
        Application.Selector.setMock(selector);
        Application.UnitOfWork.setMock(uow);

        Test.startTest();
        Integer result = InvoicingService.invoiceWonOpportunities(null);
        Test.stopTest();

        Assert.areEqual(0, result, 'Null input must return 0');
        ((IBillingGateway) mocks.verify(gateway, fflib_ApexMocks.NEVER)).authenticate();
        ((IBillingGateway) mocks.verify(gateway, fflib_ApexMocks.NEVER))
            .createInvoice((Id) fflib_Match.anyId(), (Decimal) fflib_Match.anyDecimal());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, fflib_ApexMocks.NEVER))
            .registerDirty((SObject) fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, fflib_ApexMocks.NEVER)).commitWork();
    }

