    // ---------------------------------------------------------------------
    // Authentication
    // ---------------------------------------------------------------------

    @IsTest
    static void authenticationFailureThrowsInvoicingExceptionAndInvoicesNothing() {
        fflib_ApexMocks mocks = new fflib_ApexMocks();
