        Set<Id> oppIds = new Set<Id>{ oppId };
        Decimal amount = 1000;
        List<Opportunity> opps = new List<Opportunity>{ buildOpp(oppId, accountId, CLOSED_WON, amount) };

        String gatewayMessage = 'Authentication failed: Service Unavailable';

        mocks.startStubbing();
        ((IBillingGateway) mocks.doThrowWhen(new BillingException(gatewayMessage), gateway)).authenticate();
        mocks.when(gateway.createInvoice(accountId, amount)).thenReturn('INV-0001');
        mocks.when(selector.sObjectType()).thenReturn(Opportunity.SObjectType);
        mocks.when(selector.selectById(oppIds)).thenReturn(opps);
        mocks.stopStubbing();

        Application.Service.setMock(IBillingGateway.class, gateway);
