        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, fflib_ApexMocks.NEVER))
            .registerDirty((SObject) fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) mocks.verify(uow, fflib_ApexMocks.NEVER)).commitWork();

        // the record was never touched
        Assert.isNull(opps[0].NextStep, 'NextStep must not be set when authentication fails');
        Assert.isNull(opps[0].Description, 'Description must not be set when authentication fails');
    }

