/**
 * Pure unit tests for OpportunitiesService.applyDiscounts.
 *
 * No DML, no SOQL: the domain (IOpportunities), the selector (IOpportunitiesSelector) and the
 * unit of work (fflib_ISObjectUnitOfWork) are all ApexMocks mocks injected through the
 * Application factories. The Opportunities domain logic itself is covered by its own tests.
 */
@IsTest
private class OpportunitiesServiceTest {

    private static final Decimal VALID_DISCOUNT = 20;

    /** Holds the mocks of one test so that assertions can be made against them. */
    private class Fixture {
        fflib_ApexMocks mocks;
        fflib_ISObjectUnitOfWork uowMock;
        IOpportunitiesSelector selectorMock;
        IOpportunities domainMock;
        Set<Id> opportunityIds;
        List<Opportunity> selectedOpportunities;
    }

    // ---------------------------------------------------------------------------------------
    // Happy path
    // ---------------------------------------------------------------------------------------

    @IsTest
    static void applyDiscounts_withValidInput_appliesDiscountOnDomainThenCommitsOnce() {
        // Given
        Fixture f = setup();

        // When
        Test.startTest();
        OpportunitiesService.applyDiscounts(f.opportunityIds, VALID_DISCOUNT);
        Test.stopTest();

        // Then: the opportunities are selected by the requested ids, exactly once
        ((IOpportunitiesSelector) f.mocks.verify(f.selectorMock, 1)).selectById(f.opportunityIds);

        // ...the discount is applied once on the domain, with the percentage unchanged and the
        // unit of work obtained from Application.UnitOfWork
        ((IOpportunities) f.mocks.verify(f.domainMock, 1)).applyDiscount(VALID_DISCOUNT, f.uowMock);

        // ...and the unit of work is committed exactly once
        ((fflib_ISObjectUnitOfWork) f.mocks.verify(f.uowMock, 1)).commitWork();

        // ...with commitWork() happening only after the discount has been applied
        fflib_InOrder inOrder = new fflib_InOrder(f.mocks, new List<Object>{ f.domainMock, f.uowMock });
        ((IOpportunities) inOrder.verify(f.domainMock)).applyDiscount(VALID_DISCOUNT, f.uowMock);
        ((fflib_ISObjectUnitOfWork) inOrder.verify(f.uowMock)).commitWork();
    }

    @IsTest
    static void applyDiscounts_withSmallestPositivePercentage_isAccepted() {
        // Given
        Fixture f = setup();
        Decimal discount = 0.01;

        // When
        Test.startTest();
        OpportunitiesService.applyDiscounts(f.opportunityIds, discount);
        Test.stopTest();

        // Then
        ((IOpportunities) f.mocks.verify(f.domainMock, 1)).applyDiscount(discount, f.uowMock);
        ((fflib_ISObjectUnitOfWork) f.mocks.verify(f.uowMock, 1)).commitWork();
    }

    @IsTest
    static void applyDiscounts_withUpperBoundaryPercentage_isAccepted() {
        // Given
        Fixture f = setup();
        Decimal discount = 50;

        // When
        Test.startTest();
        OpportunitiesService.applyDiscounts(f.opportunityIds, discount);
        Test.stopTest();

        // Then
        ((IOpportunities) f.mocks.verify(f.domainMock, 1)).applyDiscount(discount, f.uowMock);
        ((fflib_ISObjectUnitOfWork) f.mocks.verify(f.uowMock, 1)).commitWork();

        fflib_InOrder inOrder = new fflib_InOrder(f.mocks, new List<Object>{ f.domainMock, f.uowMock });
        ((IOpportunities) inOrder.verify(f.domainMock)).applyDiscount(discount, f.uowMock);
        ((fflib_ISObjectUnitOfWork) inOrder.verify(f.uowMock)).commitWork();
