    // ---------------------------------------------------------------------------------------
    // Helpers
    // ---------------------------------------------------------------------------------------

    /**
     * Creates the mocks, stubs them and injects them into the Application factories.
     */
    private static Fixture setup() {
        Fixture f = new Fixture();
        f.mocks = new fflib_ApexMocks();
        f.uowMock = (fflib_ISObjectUnitOfWork) f.mocks.mock(fflib_SObjectUnitOfWork.class);
        f.selectorMock = (IOpportunitiesSelector) f.mocks.mock(OpportunitiesSelector.class);
        f.domainMock = (IOpportunities) f.mocks.mock(Opportunities.class);

        Id opportunityId1 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        Id opportunityId2 = fflib_IDGenerator.generate(Opportunity.SObjectType);
        f.opportunityIds = new Set<Id>{ opportunityId1, opportunityId2 };
        f.selectedOpportunities = new List<Opportunity>{
            new Opportunity(Id = opportunityId1, Name = 'Opportunity 1', Amount = 1000),
            new Opportunity(Id = opportunityId2, Name = 'Opportunity 2', Amount = 2500)
        };

        f.mocks.startStubbing();
        // sObjectType() is what the factories use as the key when registering a mock
        f.mocks.when(f.selectorMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        f.mocks.when(f.selectorMock.selectById(f.opportunityIds)).thenReturn(f.selectedOpportunities);
        f.mocks.when(f.domainMock.sObjectType()).thenReturn(Opportunity.SObjectType);
        f.mocks.stopStubbing();

        Application.UnitOfWork.setMock(f.uowMock);
        Application.Selector.setMock(f.selectorMock);
        // Explicit cast: DomainFactory overloads setMock(fflib_ISObjectDomain) / setMock(fflib_IDomain)
        Application.Domain.setMock((fflib_ISObjectDomain) f.domainMock);

        return f;
    }

    /**
     * Asserts that the given percentage is rejected with OpportunitiesServiceException and that
     * neither the selector, the domain nor the unit of work is touched.
     */
    private static void assertRejectedPercentage(Decimal discountPercentage) {
        // Given
        Fixture f = setup();
        Boolean exceptionThrown = false;

        // When
        Test.startTest();
        try {
            OpportunitiesService.applyDiscounts(f.opportunityIds, discountPercentage);
        } catch (OpportunitiesService.OpportunitiesServiceException e) {
            exceptionThrown = true;
            Assert.isTrue(
                String.isNotBlank(e.getMessage()),
                'The exception should carry a meaningful message'
            );
        }
        Test.stopTest();

        // Then
        Assert.isTrue(
            exceptionThrown,
            'Expected OpportunitiesServiceException for discount percentage ' + discountPercentage
        );
        verifyNothingHappened(f);
    }

    /**
     * Verifies that nothing was selected, applied or committed.
     */
    private static void verifyNothingHappened(Fixture f) {
        ((IOpportunitiesSelector) f.mocks.verify(f.selectorMock, f.mocks.never()))
            .selectById((Set<Id>) fflib_Match.anyObject());

        ((IOpportunities) f.mocks.verify(f.domainMock, f.mocks.never()))
            .applyDiscount(fflib_Match.anyDecimal(), (fflib_ISObjectUnitOfWork) fflib_Match.anyObject());

        ((fflib_ISObjectUnitOfWork) f.mocks.verify(f.uowMock, f.mocks.never()))
            .registerDirty(fflib_Match.anySObject());
        ((fflib_ISObjectUnitOfWork) f.mocks.verify(f.uowMock, f.mocks.never()))
            .commitWork();
    }
