/**
 * Pure unit tests for the Contacts domain class.
 *
 * No DML and no SOQL: the domain is driven through fflib's mock trigger database
 * (fflib_SObjectDomain.Test.Database) and fflib_SObjectDomain.triggerHandler, which
 * runs the before and after phases exactly as the real trigger would.
 */
@IsTest
private class ContactsTest {

    // ------------------------------------------------------------------
    // onApplyDefaults (insert)
    // ------------------------------------------------------------------

    @IsTest
    static void onInsert_blankLeadSourceDefaultsToWeb() {
        Contact nullSource = new Contact(LastName = 'NullSource');
        Contact emptySource = new Contact(LastName = 'EmptySource', LeadSource = '');
        Contact whitespaceSource = new Contact(LastName = 'WhitespaceSource', LeadSource = '   ');
        List<Contact> records = new List<Contact>{ nullSource, emptySource, whitespaceSource };

        fflib_SObjectDomain.Test.Database.onInsert(records);
        fflib_SObjectDomain.triggerHandler(Contacts.class);

        Assert.areEqual('Web', nullSource.LeadSource, 'Null LeadSource should default to Web');
        Assert.areEqual('Web', emptySource.LeadSource, 'Empty LeadSource should default to Web');
        Assert.areEqual('Web', whitespaceSource.LeadSource, 'Whitespace LeadSource should default to Web');
        Assert.areEqual(0, fflib_SObjectDomain.Errors.getAll().size(), 'No validation errors expected');
    }

    @IsTest
    static void onInsert_existingLeadSourceIsKept() {
        Contact partner = new Contact(LastName = 'Partner', LeadSource = 'Partner Referral');
        Contact phone = new Contact(LastName = 'Phone', LeadSource = 'Phone Inquiry');
        Contact blank = new Contact(LastName = 'Blank');
        List<Contact> records = new List<Contact>{ partner, blank, phone };

