/**
 * Creates a single NPSP Household Account for a group of new Contacts.
 *
 * NPSP (Household Account model) creates one household per Contact that is inserted
 * without an AccountId. To end up with exactly ONE household for the whole family, the
 * first (primary) contact is inserted alone so that NPSP creates its household, names it
 * and sets npe01__One2OneContact__c; the remaining contacts are then inserted into that
 * same household, which makes NPSP re-run household naming / greetings for all members.
 */
public with sharing class HouseholdService {

    private static final String HOUSEHOLD_RECORD_TYPE = 'HH_Account';

    public static Id createHousehold(List<Contact> members) {
        if (members == null || members.isEmpty()) {
            throw new IllegalArgumentException('members must contain at least one Contact');
        }
        for (Contact member : members) {
            if (member == null) {
                throw new IllegalArgumentException('members must not contain null entries');
            }
            if (member.Id != null) {
                throw new IllegalArgumentException('members must be new Contacts (no Id)');
            }
            // Make sure NPSP decides the household; never let a stray AccountId leak in.
            member.AccountId = null;
        }

        Savepoint sp = Database.setSavepoint();
        try {
            // 1. Insert the primary contact on its own -> NPSP creates exactly one household
            //    (HH_Account record type), names it and sets it as the primary contact.
            Contact primary = members[0];
            Database.insert(primary, AccessLevel.USER_MODE);

            Contact insertedPrimary = [
                SELECT Id, AccountId, Account.RecordType.DeveloperName
                FROM Contact
                WHERE Id = :primary.Id
                WITH USER_MODE
                LIMIT 1
            ];
            Id householdId = insertedPrimary.AccountId;
            if (householdId == null
                    || insertedPrimary.Account.RecordType.DeveloperName != HOUSEHOLD_RECORD_TYPE) {
                throw new HouseholdServiceException(
                    'NPSP did not create a Household Account for the primary contact. '
                    + 'Verify that the NPSP Household Account model is active.');
            }

            // 2. Insert the remaining family members directly into that household.
            if (members.size() > 1) {
                List<Contact> others = new List<Contact>();
                for (Integer i = 1; i < members.size(); i++) {
                    Contact member = members[i];
                    member.AccountId = householdId;
                    others.add(member);
                }
                Database.insert(others, AccessLevel.USER_MODE);
            }

            // 3. Guarantee the first contact is the household's primary contact.
            Account household = [
                SELECT Id, npe01__One2OneContact__c
                FROM Account
                WHERE Id = :householdId
                WITH USER_MODE
                LIMIT 1
            ];
            if (household.npe01__One2OneContact__c != primary.Id) {
                household.npe01__One2OneContact__c = primary.Id;
                Database.update(household, AccessLevel.USER_MODE);
            }

            return householdId;
        } catch (Exception e) {
            Database.rollback(sp);
            throw e;
        }
    }

    public class HouseholdServiceException extends Exception {}
}
